```java
public static int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}
```

```java
public static int countDivisible(int lo, int hi, int k) {
    int count = 0;
    for (int x = lo; x <= hi; x++) {
        if (digitSum(x) % k == 0) {
            count++;
        }
    }
    return count;
}
```

```java
public class ScoreKeeper {
    private static int totalScores = 0;
    private String name;
    private int sum;
    private int count;
    private int best;
    public ScoreKeeper(String name) {
        this.name = name;
        best = -1;
    }
    public void addScore(int s) {
        sum += s;
        count++;
        totalScores++;
        if (s > best) {
            best = s;
        }
    }
    public double getAverage() {
        if (count == 0) {
            return 0.0;
        }
        return (double) sum / count;
    }
    public int getBest() {
        return best;
    }
    public static int getTotalScores() {
        return totalScores;
    }
}
```

